pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address fuzz_owner, address fuzz_caller) public {
        // fuzz_owner is the smartfix_owner; fuzz_caller is the caller of sudicideAnyone
        vm.assume(fuzz_owner != address(0));
        vm.assume(fuzz_caller != address(0));

        // Deploy a fresh contract with fuzz_owner as the actual smartfix_owner
        vm.prank(fuzz_owner);
        c = new C();

        // When the owner calls, the call must succeed (not revert) according to the original logic
        // The buggy version reverts for everyone, so when fuzz_caller == fuzz_owner, the assertion fails
        bool ok;
        vm.prank(fuzz_caller);
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }

        // General rule: if caller is the smartfix_owner, the call must succeed (not revert).
        // The buggy version always reverts, so it violates this when fuzz_caller == fuzz_owner.
        assertTrue(fuzz_caller != c.smartfix_owner() || ok);
    }
}

