pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address nonOwner) public {
        vm.assume(owner != address(0));
        vm.assume(nonOwner != owner);
        // Transfer ownership to the fuzzed owner address
        vm.prank(address(c).balance == 0 ? address(0) : address(0));
        // Actually we need to set the owner. The contract sets owner = msg.sender in constructor.
        // We can't change it, so we must use the deployment address as the owner.
        // Let the fuzzer pick an actor; if it's not the owner, the call should revert.
        address originalOwner = c.smartfix_owner();
        bool calledByOwner = (owner == originalOwner);

        // Prank as the fuzzed 'owner' (which may or may not be the real owner)
        vm.prank(owner);
        try c.sudicideAnyone() {
            // call succeeded -> owner passed the require
            assertTrue(calledByOwner); // only the real owner should succeed
            // After successful selfdestruct, the contract should have no code
            uint256 codeSize;
            assembly { codeSize := extcodesize(address(c)) }
            // In the reference, codeSize becomes 0 after selfdestruct.
            // In the mutant, since selfdestruct is removed, codeSize remains > 0.
            assertTrue(codeSize == 0);
        } catch {
            // call reverted -> either require failed or something else
            // If it reverted, owner must NOT be the real owner (or the call had no effect)
            assertTrue(!calledByOwner);
        }
    }
}

