contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address relay, uint256 funds) public {
        vm.assume(relay != address(0) && relay != address(this) && relay != address(c) && relay != msg.sender);
        vm.assume(funds > 0);
        // Deploy an adversarial relay that calls sudicideAnyone on behalf of the owner via prank
        // The relay will be funded and will call c.sudicideAnyone() from its own address (tx.origin will be relay)
        // After call, we check that c's code size is 0 (destroyed) and relay (tx.origin) received all ether.
        Relay r = new Relay();
        vm.deal(address(c), funds);
        vm.prank(address(r));
        r.forward(address(c));
        uint256 codeSize;
        assembly { codeSize := extcodesize(sload(c.slot)) }
        bool destroyed = codeSize == 0;
        assertTrue(destroyed);
    }
}

contract Relay {
    function forward(address target) external {
        C(target).sudicideAnyone();
    }
}

